package hotel.web;

import hotel.reservations.Identification;
import hotel.reservations.RatePlan;
import java.time.LocalDate;
import java.util.Optional;

/**
 * The JSON body of POST /reservations. Every field is required, except that the guest is identified in one
 * of three ways: guestCpf, or companyCnpj with companyName, or guestPassport with guestCountry.
 */
public record CreateReservationRequest(
        Integer roomNumber,
        String guestName,
        String guestEmail,
        String guestCpf,
        String companyCnpj,
        String companyName,
        String guestPassport,
        String guestCountry,
        LocalDate checkIn,
        LocalDate checkOut,
        Integer guests,
        RatePlan ratePlan) {

    /** The way the guest is identified; empty unless exactly one way is given, whole. */
    Optional<Identification> identification() {
        boolean cpf = filled(guestCpf);
        boolean company = filled(companyCnpj) && filled(companyName);
        boolean passport = filled(guestPassport) && filled(guestCountry);
        boolean anyField = cpf || filled(companyCnpj) || filled(companyName)
                || filled(guestPassport) || filled(guestCountry);
        boolean oneWayOnly = (cpf ? 1 : 0) + (company ? 1 : 0) + (passport ? 1 : 0) == 1;
        boolean noStrayField = anyField && (cpf ? 1 : 0) + (filled(companyCnpj) ? 1 : 0) + (filled(companyName) ? 1 : 0)
                + (filled(guestPassport) ? 1 : 0) + (filled(guestCountry) ? 1 : 0)
                == (cpf ? 1 : company ? 2 : 2);
        if (!oneWayOnly || !noStrayField) {
            return Optional.empty();
        }
        if (cpf) {
            return Optional.of(new Identification.Cpf(guestCpf));
        }
        if (company) {
            return Optional.of(new Identification.Company(companyCnpj, companyName));
        }
        return Optional.of(new Identification.Passport(guestPassport, guestCountry));
    }

    private static boolean filled(String text) {
        return text != null && !text.isBlank();
    }
}
