                LocalDate.parse("2027-03-10"), LocalDate.parse("2027-03-12"), 1, RatePlan.STANDARD);
        Reservation reservation = service.create(request);
        service.confirm(reservation.id());

        ReservationDocument document = service.receiptCopy(reservation.id());

        assertEquals(\"""
                Booking receipt no. 1
                Guest: John Smith (passport X1234567, United Kingdom)
                Room: 201 (DELUXE)
                Check-in: 2027-03-10 | Check-out: 2027-03-12 | 2 nights
                Nights: BRL 779.80
                Total: BRL 779.80
                \""", document.text());
        assertEquals("X1234567", document.guestPassport());
        assertNull(document.companyCnpj());
    }

    @Test
    void theBookingReceiptShowsTheDiscountAndASingleNight() {
        Reservation reservation = service.create(new NewReservation(301,
                new Guest("John Smith", "john@example.com", new Identification.Passport("X1", "Chile")),
                LocalDate.parse("2027-03-10"), LocalDate.parse("2027-03-11"), 1, RatePlan.NON_REFUNDABLE));
